do $$ begin if (select count(*) from public.entities where slug in ('lee-chuan-how','m-kulasegaran','sivakumar-varatharaju-naidu') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0021: concurrent ownership or identity change'; end if; end $$;

